dtsPropsFor.ScreenShell:
/** Rendered as the screen's <h1>. On /tarefas/[id] this is the TASK TITLE — TaskDetail does not render one. */
title: string;
/** Optional second line. /tarefas/[id] passes `[job.name, job.address].filter(Boolean).join(' \u00b7 ')`. */
subtitle?: string;
/** The screen body. ScreenShell is overflow-hidden and carries NO scroller — the caller supplies one, or content is clipped. */
children: React.ReactNode;

dtsPropsFor.EmptyState:
text: string;
/** The one thing worth doing next. Omit when there is nothing to offer. */
cta?: { href: string; label: string };

dtsPropsFor.StatusBadge:
/** A task status. null renders nothing. */
status: string | null;
locale: 'pt-PT' | 'es-ES' | 'en-US';
/** Opt back in to the 'pending' badge. Off by default: pending is the status of almost every open task, so a badge for it would occupy the one slot real state belongs in. */
showPending?: boolean;

dtsPropsFor.TaskBoardList:
tasks: Array<{ id: string; title: string; status: string; description: string | null; duration_days: number | null; materials: string[] | null; job_id: string | null; job_name: string | null; job_status: string | null; worker_name: string | null; assignee_worker_id: string | null; start_date: string | null; due_date: string | null; active_today: boolean; active_tomorrow: boolean; overdue: boolean; days_overdue: number; at_risk: boolean; risk_blocked: boolean; risk_late_start: boolean; risk_due_soon: boolean; risk_late_dependency: boolean; risk_paused_job: boolean; late_dependency_titles: string[]; depends_on_titles: string[]; confirmation_state?: string | null; confirmed_at?: string | null; last_reminder_at?: string | null; proof_count?: number | null }>;
/** Shown via EmptyState when `tasks` is empty. */
empty: string;
groupBy: 'date' | 'obra' | 'agenda';
locale: 'pt-PT' | 'es-ES' | 'en-US';
/** Today in Europe/Lisbon, from the SAME lisbon_today() clock the rows come from — never from the browser. Required in practice by the 'agenda' grouping. */
today?: string | null;
/** Per-row slot in the narrow action column (e.g. Concluir/Reabrir). A render prop so this package never imports a mutation. */
renderExtra?: (task: TaskBoardListProps['tasks'][number]) => React.ReactNode;
/** Second per-row slot, full width and below the risk reasons. */
renderBelow?: (task: TaskBoardListProps['tasks'][number]) => React.ReactNode;

dtsPropsFor.ObrasList:
/** Rows of the dashboard_obras view. Since migration 0038 this carries PAUSED obras as well as active ones — check `status` rather than assuming every row is active. */
obras: Array<{ id: string | null; name: string | null; address: string | null; status: string | null; pendentes: number | null; concluidas: number | null; company_id: string | null }>;
empty: string;
locale: 'pt-PT' | 'es-ES' | 'en-US';
/** Overdue task count per obra id, rendered red beside the name. */
overdueByObra?: Record<string, number>;

dtsPropsFor.TimelineList:
tasks: Array<{ id: string; title: string; status: string; start_date: string | null; due_date: string | null; duration_days: number | null; materials: string[] | null; assignee_name: string | null; depends_on_titles: string[] }>;
empty: string;
locale: 'pt-PT' | 'es-ES' | 'en-US';
renderExtra?: (task: TimelineListProps['tasks'][number]) => React.ReactNode;

dtsPropsFor.MaterialsList:
/** One group per obra. Above THREE groups the list opens collapsed. */
groups: Array<{ obraId: string | null; obraName: string; items: Array<{ material: string; forTasks: Array<{ id: string; title: string; materials: string[] }> }>; tasks: Array<{ id: string; title: string; materials: string[] }> }>;
empty: string;
/** Heading for the group holding work with no obra attached. */
noJobLabel: string;
/** e.g. "para: Pintar tecto" — says WHY each item is on the list. */
forLabel: (tasks: string[]) => string;
/** e.g. "4 materiais" — what a collapsed group tells you without opening. */
countLabel?: (n: number) => string;
/** Shown inside a group whose obra has work but nothing recorded yet. */
emptyGroupLabel?: string;
seeJobLabel?: string;
/** The "add material" control. Injected, never built here — this package owns no mutation. */
renderGroupAction?: (group: MaterialsListProps['groups'][number]) => React.ReactNode;
/** Replaces the plain material name with something tappable. */
renderItem?: (item: MaterialsListProps['groups'][number]['items'][number], group: MaterialsListProps['groups'][number]) => React.ReactNode;

dtsPropsFor.TaskDetail:
task: { id: string; title: string; status: string; description: string | null; duration_days: number | null; materials: string[] | null; job_id: string | null; job_name: string | null; job_status: string | null; worker_name: string | null; assignee_worker_id: string | null; start_date: string | null; due_date: string | null; active_today: boolean; active_tomorrow: boolean; overdue: boolean; days_overdue: number; at_risk: boolean; risk_blocked: boolean; risk_late_start: boolean; risk_due_soon: boolean; risk_late_dependency: boolean; risk_paused_job: boolean; late_dependency_titles: string[]; depends_on_titles: string[]; confirmation_state?: string | null; confirmed_at?: string | null; last_reminder_at?: string | null; proof_count?: number | null };
job: { id: string; name: string; address: string | null; client_name: string | null; status: string } | null;
worker: { id: string; name: string; trade: string | null; phone: string | null; active: boolean } | null;
/** Everyone else on this task (issue #44) — helpers, never the assignee. Names only. */
collaborators?: Array<{ id: string; name: string }>;
/** Proof of the work, newest first. `url` is a SHORT-LIVED signed URL minted per request — never cache it, and the page rendering it must be dynamic. */
photos?: Array<{ id: string; url: string; source: string; createdAt: string }>;
locale: 'pt-PT' | 'es-ES' | 'en-US';
/** Replaces the read-only assignee line with the worker picker. */
renderAssignee?: () => React.ReactNode;
/** The "who else is helping" control. Its PRESENCE also makes the section render when nobody is helping yet. */
renderCollaborators?: () => React.ReactNode;
/** The "edit materials" control. Its PRESENCE also makes the section render on a task with an empty list. */
renderMaterials?: () => React.ReactNode;
/** Concluir/Reabrir. */
renderActions?: () => React.ReactNode;
